// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler, ERC20, CoolerFactory} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    MockERC20 token;

    function setUp() public {
        c = new Cooler();
        token = new MockERC20();
        CoolerFactory f = new CoolerFactory();
        // create a real cooler clone whose immutable args (owner/collateral/debt/factory) are set correctly
        address cooler = f.generateCooler(token, token);
        c = Cooler(cooler);
    }

    function testFuzz_property(address to_, address lender, uint256 amount) public {
        vm.assume(to_ != lender);
        vm.assume(lender != address(0));
        amount = bound(amount, 1, 1e30);

        // borrower requests a loan (collateral transfer is mocked and always succeeds)
        vm.prank(address(0xB0B));
        c.requestLoan(amount, 0, 1, 1 days);

        // lender clears the request, becoming loans[0].lender
        vm.prank(lender);
        c.clearRequest(0, true, false);

        // the lender approves to_
        vm.prank(lender);
        c.approveTransfer(to_, 0);

        // General rule: after the lender approves to_ for a loan, the approval for
        // that loan is exactly to_ (the approved address, never the caller instead).
        assertTrue(c.approvals(0) == to_);
    }
}

contract MockERC20 is ERC20 {
    constructor() ERC20("mock", "M", 18) {}

    function transfer(address, uint256) public override returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) public override returns (bool) {
        return true;
    }
}
